836|{
837|    // Fast path: this node is dying, so maintaining _firstChild/_lastChild and
838|    // sibling _prev/_next links is unnecessary. Only _parent must be zeroed to
839|    // satisfy the MarkInUse assertion inside DeleteNode.
840|    XMLNode *currentChild = _firstChild;
841|    while (currentChild != NULL) {
842|        XMLNode *next = currentChild->_next;
843|        currentChild->_parent = 0;
844|        DeleteNode(currentChild);
845|        currentChild = next;
846|    }
847|
848|    if ( _parent ) {
849|        _parent->Unlink( this );
850|    }
